// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { Envelope, EnvelopeAddress, EnvelopeFront, EnvelopeLetter, EnvelopeSender, EnvelopeTrigger } from "@/components/ui/envelope";
import { Stamp } from "@/components/ui/stamp";
type Newsletter01EnvelopeProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  stamped: boolean;
};
const Newsletter01Envelope = defineUi<Newsletter01EnvelopeProps>("Newsletter01Envelope", ["open", "onOpenChange", "stamped"], (_props, {
  slots: _slots
}) => {
  const open = computed(() => _props["open"]);
  const onOpenChange = computed(() => _props["onOpenChange"]);
  const stamped = computed(() => _props["stamped"]);
  return () => {
    return <div class="relative mx-auto flex aspect-[40/39] w-full max-w-sm flex-col justify-end">
      <Envelope stock="kraft" stamp="tomato" postmark open={open.value} onOpenChange={onOpenChange.value} seed="newsletter-envelope" tilt={1}>
        <EnvelopeFront>
          <EnvelopeSender>
            Penmark
            <br />
            Lisbon
          </EnvelopeSender>
          <EnvelopeAddress class="text-[1.15rem]">
            <p>You</p>
            <p>Your inbox</p>
            <p>Sunday morning</p>
          </EnvelopeAddress>
          <EnvelopeTrigger>Peek inside the Sunday letter</EnvelopeTrigger>
        </EnvelopeFront>
        <EnvelopeLetter>
          <p class="font-script text-2xl leading-none font-bold">Sunday letter, no. 41</p>
          <p class="mt-1 text-sm">On buying too many pens, and one very good link.</p>
        </EnvelopeLetter>
      </Envelope>
      {stamped.value ? <Stamp text="Subscribed" ink="green" w={150} h={50} tilt={-8} ghost seed="newsletter-stamp" class="pointer-events-none absolute end-3 bottom-5 z-30 animate-in zoom-in-[1.7] fade-in-0 duration-(--ll-dur-pop)" /> : null}
    </div>;
  };
});
export { Newsletter01Envelope };

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, useId, shallowRef } from "vue";
import { Button } from "@/components/ui/button";
import { Field, FieldDescription, FieldError, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
type Newsletter01Status = "idle" | "invalid" | "sending" | "failed" | "done";
type Newsletter01FormProps = {
  status: Newsletter01Status;
  email: string;
  onEmailChange: (email: string) => void;
  onSubmit: () => void;
  onReset: () => void;
};
const Newsletter01Form = defineUi<Newsletter01FormProps>("Newsletter01Form", ["status", "email", "onEmailChange", "onSubmit", "onReset"], (_props, {
  slots: _slots
}) => {
  const status = computed(() => _props["status"]);
  const email = computed(() => _props["email"]);
  const onEmailChange = computed(() => _props["onEmailChange"]);
  const onSubmit = computed(() => _props["onSubmit"]);
  const onReset = computed(() => _props["onReset"]);
  const id = useId();
  const inputRef = shallowRef<HTMLInputElement | null>(null);
  const doneRef = shallowRef<HTMLDivElement | null>(null);
  const bad = computed(() => status.value === "invalid" || status.value === "failed");
  watchDependencies(() => {
    if (status.value === "done") doneRef.value?.focus();
    if (status.value === "invalid" || status.value === "failed") inputRef.value?.focus();
  }, () => [status.value], false);
  return () => {
    if (status.value === "done") {
      return <div ref={doneRef} tabindex={-1} role="status" class="rounded-none outline-none">
        <p class="font-script text-3xl leading-none font-bold text-ink">You&rsquo;re on the list.</p>
        <p class="mt-2 text-lg/7 text-ink-soft">
          We sent a note to <strong class="font-bold text-ink">{email.value}</strong>. Click the link inside to confirm, and the first letter lands on Sunday.
        </p>
        <Button type="button" variant="link" size="sm" onClick={onReset.value} class="-ms-3 mt-1">
          Use a different address
        </Button>
      </div>;
    }
    return <form novalidate onSubmit={(e: SubmitEvent) => {
      e.preventDefault();
      onSubmit.value();
    }}>
      <Field data-invalid={bad.value || undefined}>
        <FieldLabel for={`${id}-email`}>Your email address</FieldLabel>
        <div class="flex flex-col gap-3 @lg:flex-row @lg:gap-4">
          <Input ref={inputRef} id={`${id}-email`} type="email" name="email" autocomplete="email" required placeholder="you@example.com" value={email.value} onChange={(e: Event) => onEmailChange.value((e.target as HTMLInputElement).value)} aria-invalid={bad.value || undefined} aria-describedby={`${id}-help${bad.value ? ` ${id}-error` : "" as const}`} class="min-w-0 @lg:flex-1" />
          <Button type="submit" disabled={status.value === "sending"}>
            {status.value === "sending" ? "Subscribing…" as const : "Subscribe" as const}
          </Button>
        </div>
        <FieldDescription id={`${id}-help`}>No spam. Leave with one click. 12,400 people read it.</FieldDescription>
        {status.value === "invalid" ? <FieldError id={`${id}-error`}>That does not look like an email address. Check it for typos?</FieldError> : null}
        {status.value === "failed" ? <FieldError id={`${id}-error`}>Something went wrong on our side. Please try again in a moment.</FieldError> : null}
      </Field>
    </form>;
  };
});
export { Newsletter01Form };
export type { Newsletter01Status };

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed, useId, shallowRef } from "vue";
import { Lettering } from "@/components/ui/lettering";
import { Paper } from "@/components/ui/paper";
import { Newsletter01Envelope } from "@/blocks/newsletter-01/components/newsletter-01-envelope";
import { Newsletter01Form, type Newsletter01Status } from "@/blocks/newsletter-01/components/newsletter-01-form";
type Newsletter01Props = {
  onSubscribe?: (email: string) => void | Promise<void>;
};
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const Newsletter01 = defineUi<Newsletter01Props>("Newsletter01", ["onSubscribe"], (_props, {
  slots: _slots
}) => {
  const onSubscribe = computed(() => _props["onSubscribe"]);
  const titleId = useId();
  const status = shallowRef<Newsletter01Status>(initialState("idle"));
  const setStatus = stateSetter(status);
  const email = shallowRef(initialState(""));
  const setEmail = stateSetter(email);
  const open = shallowRef(initialState(false));
  const setOpen = stateSetter(open);
  const submit = computed(() => async () => {
    if (!EMAIL.test(email.value.trim())) {
      setStatus("invalid");
      return;
    }
    setStatus("sending");
    try {
      await onSubscribe.value?.(email.value.trim());
      setStatus("done");
      setOpen(true);
    } catch {
      setStatus("failed");
    }
  });
  return () => {
    return <section aria-labelledby={titleId} class="@container relative w-full overflow-x-clip">
      <div class="px-8 py-14 @xl:py-20">
        <div class="mx-auto grid max-w-5xl items-center gap-x-14 gap-y-6 @3xl:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)]">
          <Paper stock="paper" tilt={false} tape="corner" tapeKind="washi-dots" seed="newsletter-card" class="px-6 py-8 @xl:px-9 @xl:py-10">
            <p class="font-type text-sm text-pencil-text">The Sunday letter</p>
            <Lettering as="h2" id={titleId} size="md" tone="marker" wobble={0.4} seed="newsletter-title" class="mt-3">
              One short letter, every Sunday
            </Lettering>
            <p class="mt-4 mb-6 text-lg/7 text-ink-soft">What we shipped, what we drew, and one good link. Three minutes, best with tea.</p>
            <Newsletter01Form status={status.value} email={email.value} onEmailChange={v => {
              setEmail(v);
              if (status.value === "invalid" || status.value === "failed") setStatus("idle");
            }} onSubmit={submit.value} onReset={() => {
              setStatus("idle");
              setEmail("");
              setOpen(false);
            }} />
          </Paper>

          <Newsletter01Envelope open={open.value} onOpenChange={setOpen} stamped={status.value === "done"} />
        </div>
      </div>
    </section>;
  };
});
export default Newsletter01;
export type { Newsletter01Props };
